changeSet.sql:
INSERT IGNORE INTO category (id, name) SELECT id, naziv FROM kategorija;

INSERT IGNORE INTO manufacturer (id, name) SELECT id, name FROM proizvodjac;

INSERT IGNORE INTO specification (id, resolution, image_sensor, wifi, screen, power, image_size, description)
    SELECT id, rezolucija, senzor_slike, wifi, ekran, napajanje, velicina_slike, opis FROM specifikacija;

INSERT IGNORE INTO client (id, first_name, last_name, age, username, password, email)
    SELECT id, ime, prezime, starost, username, password, email FROM klijent;

INSERT IGNORE INTO employee (id, first_name, last_name, username, password, email)
    SELECT id, ime, prezime, username, password, email FROM zaposleni;

INSERT IGNORE INTO camera (id, purchase_date, note, available, category_id, manufacturer_id, specification_id)
    SELECT id, datum_kupovine, napomena, dostupan, kategorija_id, proizvodjac_id, specifikacija_id FROM fotoaparat;

INSERT IGNORE INTO rental (id, start_date, end_date, price, note, camera_id, client_id, employee_id)
    SELECT id, datum_pocetka, datum_kraja, cena, napomena, fotoaparat_id, klijent_id, zaposleni_id FROM iznajmljivanje;

UPDATE category SET name = 'Compact' WHERE name = 'Kompaktni';
UPDATE category SET name = 'Action camera' WHERE name = 'Akciona kamera';
UPDATE category SET name = 'Video camera' WHERE name = 'Video kamera';

UPDATE camera SET note = 'Regularly serviced' WHERE note = 'Redovno servisiran';
UPDATE camera SET note = 'Excellent condition' WHERE note = 'Odlicno stanje';
UPDATE camera SET note = 'Compact and lightweight' WHERE note = 'Kompaktan i lagan';
UPDATE camera SET note = 'Minor scratches on the body' WHERE note = 'Ima sitne ogrebotine na kucistu';
UPDATE camera SET note = 'Nearly new, barely used' WHERE note = 'Novo, malo koriscen';
UPDATE camera SET note = 'Older model, currently out of service' WHERE note = 'Stariji model, trenutno van upotrebe';
UPDATE camera SET note = 'Professional model' WHERE note = 'Profesionalni model';
UPDATE camera SET note = 'Waterproof action camera' WHERE note = 'Vodootporna akciona kamera';
UPDATE camera SET note = 'Classic design' WHERE note = 'Klasican dizajn';
UPDATE camera SET note = 'Needs sensor cleaning, currently out of service' WHERE note = 'Zahteva ciscenje senzora, trenutno van upotrebe';

UPDATE rental SET note = 'Weekend rental' WHERE note = 'Vikend iznajmljivanje';
UPDATE rental SET note = 'Wedding rental' WHERE note = 'Iznajmljivanje za vencanje';
UPDATE rental SET note = 'Business trip' WHERE note = 'Poslovno putovanje';
UPDATE rental SET note = 'Birthday party' WHERE note = 'Rodjendanska proslava';
UPDATE rental SET note = 'Short trip' WHERE note = 'Kratak izlet';
UPDATE rental SET note = 'Commercial shoot' WHERE note = 'Snimanje reklame';
UPDATE rental SET note = 'Family trip' WHERE note = 'Porodicno putovanje';
UPDATE rental SET note = 'Conference rental' WHERE note = 'Iznajmljivanje za konferenciju';
UPDATE rental SET note = 'Summer festival' WHERE note = 'Letnji festival';
UPDATE rental SET note = 'One-day photo shoot' WHERE note = 'Jednodnevno fotografisanje';
UPDATE rental SET note = 'Winter photo shoot' WHERE note = 'Zimsko fotografisanje';
UPDATE rental SET note = 'Spring session' WHERE note = 'Prolecna sesija';
UPDATE rental SET note = 'Valentine photo shoot' WHERE note = 'Valentinovo fotografisanje';
UPDATE rental SET note = 'Spring outing' WHERE note = 'Prolecni izlet';

UPDATE specification SET power = 'Li-ion battery' WHERE power = 'Li-ion baterija';
UPDATE specification SET screen = '3.2" tilting LCD' WHERE screen = '3.2" nagibni LCD';
UPDATE specification SET screen = '3.0" tilting touchscreen' WHERE screen = '3.0" nagibni touchscreen';
UPDATE specification SET screen = 'No screen (viewfinder only)' WHERE screen = 'Bez ekrana (trazilo)';
UPDATE specification SET image_sensor = '1-inch sensor' WHERE image_sensor = '1-incni senzor';
UPDATE specification SET image_sensor = 'CMOS action camera' WHERE image_sensor = 'CMOS akciona kamera';
UPDATE specification SET description = 'DSLR camera ideal for beginners and enthusiasts.' WHERE description = 'DSLR fotoaparat idealan za pocetnike i entuzijaste.';
UPDATE specification SET description = 'Professional DSLR with excellent low-light performance.' WHERE description = 'Profesionalni DSLR sa odlicnim performansama pri slaboj svetlosti.';
UPDATE specification SET description = 'Compact mirrorless camera for everyday use.' WHERE description = 'Kompaktan bezogledalni fotoaparat za svakodnevnu upotrebu.';
UPDATE specification SET description = 'Retro design with modern performance.' WHERE description = 'Retro dizajn sa modernim performansama.';
UPDATE specification SET description = 'An excellent choice for video work.' WHERE description = 'Odlican izbor za video snimanje.';
UPDATE specification SET description = 'Compact mirrorless camera.' WHERE description = 'Kompaktan mirrorless fotoaparat.';
UPDATE specification SET description = 'Legendary build and optical quality.' WHERE description = 'Legendarni kvalitet izrade i optike.';
UPDATE specification SET description = 'Waterproof camera for extreme sports.' WHERE description = 'Vodootporna kamera za ekstremne sportove.';
UPDATE specification SET description = 'Rugged, weather-sealed DSLR.' WHERE description = 'Robustan DSLR otporan na vremenske uslove.';
UPDATE specification SET description = 'A unique sensor delivering exceptional colour sharpness.' WHERE description = 'Jedinstven senzor za izuzetnu ostrinu boja.';

UPDATE client SET first_name = 'Test', last_name = 'Client', username = 'client', password = 'client123', email = 'client@example.com' WHERE username = 'klijent';
UPDATE employee SET first_name = 'Test', last_name = 'Employee', username = 'employee', password = 'employee123' WHERE username = 'zaposleni';
UPDATE employee SET email = REPLACE(email, '@fotorent.com', '@rentacamera.com') WHERE email LIKE '%@fotorent.com';

